10: export function validateGraph(graph, objective) {
11:   if (!graph || !sameObjective(graph.objective, objective) || !nonempty(graph.summary)
12:     || !Array.isArray(graph.nodes) || graph.nodes.length < 1 || graph.nodes.length > 8) {
13:     throw new Error('Expected the original objective, a research summary, and 1–8 nodes.');
14:   }
15:   const nodes = new Map();
16:   for (const node of graph.nodes) {
17:     if (!node || typeof node.id !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(node.id)
18:       || !nonempty(node.title) || !nonempty(node.reason)
19:       || !Array.isArray(node.evidence) || !node.evidence.length || !node.evidence.every(nonempty)
20:       || !Array.isArray(node.dependsOn) || !node.dependsOn.every(nonempty) || nodes.has(node.id)) {
21:       throw new Error('Each node needs a unique slug id, title, reason, evidence, and dependsOn array.');
22:     }
23:     nodes.set(node.id, node);
24:   }
25:   const visiting = new Set();
26:   const visited = new Set();
27:   function visit(id) {
28:     if (!nodes.has(id)) throw new Error(`Unknown dependency: ${id}`);
29:     if (visiting.has(id)) throw new Error(`Dependency cycle: ${id}`);
30:     if (visited.has(id)) return;
31:     visiting.add(id);
32:     for (const dependency of nodes.get(id).dependsOn) visit(dependency);
33:     visiting.delete(id);
34:     visited.add(id);
35:   }
36:   for (const id of nodes.keys()) visit(id);
37:   // Outcomes are absent from a freshly planned graph and appended by `tag record` afterwards. They
38:   // are held on the graph rather than on the node because node ids do not survive replanning —
39:   // the seventh run's ids and the fourteenth's have nothing in common — and an outcome is evidence
40:   // about work that was really performed, which must outlive the node that happened to propose it.
41:   if (graph.outcomes !== undefined && (!Array.isArray(graph.outcomes)
42:     || !graph.outcomes.every(item => item && nonempty(item.node) && nonempty(item.title)
43:       && nonempty(item.at) && nonempty(item.outcome)))) {
44:     throw new Error('Recorded outcomes must be a list of {node, title, at, outcome}.');
45:   }
46:   // The asked objective is authoritative; the echo only had to agree with it.
47:   graph.objective = objective;
48:   return graph;
49: }
