44: async function request(path, options, fetchImpl) {
45:   let response;
46:   try {
47:     response = await fetchImpl(`${API}${path}`, { ...options, signal: AbortSignal.timeout(120_000) });
48:   } catch (error) {
49:     throw new Error(`OpenRouter unavailable (${error.cause?.code ?? error.name}). No retry was made.`);
50:   }
51:   if (!response.ok) throw new Error(`OpenRouter HTTP ${response.status}. No retry was made.`);
52:   return response.json();
53: }
