55: // A recorded outcome that the planner never reads changes nothing: run 9 proposed the very node
56: // whose outcome said it had just been worked, because it never opened the graph. Instructions do
57: // not reliably produce a tool call, so the durable state is supplied rather than offered.
58: async function priorGraph(path) {
59:   let text;
60:   try {
61:     text = await readFile(path, 'utf8');
62:   } catch (error) {
63:     if (error.code === 'ENOENT') return null;
64:     throw new Error(`Could not read the durable graph at ${path}: ${error.message}`);
65:   }
66:   const graph = JSON.parse(text);
67:   validateGraph(graph, graph?.objective);
68:   // Only the outcomes. Handed whole nodes, two runs returned them: same ids, same reasons, same
69:   // evidence strings, copied line numbers, and one file read between them. The node bodies are
70:   // answer-shaped and get copied; the outcomes are the part that exists nowhere else.
71:   return (graph.outcomes ?? []).map(item =>
72:     `- ${item.title} (recorded ${item.at}): ${item.outcome}`);
73: }
