75: export async function plan(objective, directory, {
76:   apiKey = process.env.OPENROUTER_API_KEY,
77:   fetchImpl = fetch,
78:   graphPath = join(directory, 'graph', 'graph.json'),
79: } = {}) {
80:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
81:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
82:   const outcomes = await priorGraph(graphPath);
83:   const prior = outcomes?.length ? outcomes : null;
84:   const investigate = await repositoryTools(directory);
85:   const output = join(directory, '.tag');
86:   try {
87:     await mkdir(output, { mode: 0o700 });
88:   } catch (error) {
89:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
90:     throw error;
91:   }
92:   await writeFile(join(output, '.gitignore'), '*\n', { flag: 'wx', mode: 0o600 });
93:   // A failed run is an experimental result: keep what it did and what it answered.
94:   const attempt = { model: MODEL, createdAt: new Date().toISOString(), requests: 0, costUsd: 0, investigation: [] };
95:   let keep = false;
96:   try {
97:     const { data } = await request('/models', {}, fetchImpl);
98:     const model = data?.find(item => item.id === MODEL);
99:     const promptPrice = Number(model?.pricing?.prompt);
100:     const completionPrice = Number(model?.pricing?.completion);
101:     // Deliberately conservative caps, not a general-purpose cost reservation system.
102:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
103:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
104:       || Number(model.pricing.request ?? 0) !== 0) {
105:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
106:     }
107:     const messages = [
108:       { role: 'system', content: instructions },
109:       { role: 'user', content: objective },
110:     ];
111:     attempt.priorGraph = prior ? graphPath : null;
112:     let supplied = false;
113:     const investigation = attempt.investigation;
114:     const researched = () => investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result));
115:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
116:       attempt.requests = turn;
117:       // Supplied with the graph up front, a real run answered with the graph: it restated three
118:       // of its four nodes verbatim, read nothing, and cited files it had never opened. The
119:       // durable state is real input, so it is withheld until the repository has actually been
120:       // investigated, and never allowed to stand in for investigating it.
121:       if (prior && !supplied && researched()) {
122:         supplied = true;
123:         messages.push({ role: 'user', content: `Work already performed on this objective, recorded by a human after observing what each attempt actually did:\n${prior.join('\n')}\nThis list is not a plan and is not exhaustive. Continue investigating if you have not finished.` });
124:       }
125:       const body = {
126:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
127:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
128:         temperature: 0.2,
129:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
130:       };
131:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
132:         throw new Error('Research context limit reached. No graph saved; human review required.');
133:       }
134:       const response = await request('/chat/completions', {
135:         method: 'POST',
136:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
137:         body: JSON.stringify(body),
138:       }, fetchImpl);
139:       const cost = response.usage?.cost;
140:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
141:         ? attempt.costUsd + cost : null;
142:       const choice = response.choices?.[0];
143:       const message = choice?.message;
144:       if (!message || choice.finish_reason === 'length' || response.error) {
145:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
146:       }
147:       if (message.tool_calls?.length) {
148:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
149:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
150:         for (const call of message.tool_calls) {
151:           let args;
152:           let result;
153:           try {
154:             args = JSON.parse(call.function.arguments);
155:             result = await investigate(call.function.name, args);
156:           } catch {
157:             // Do not return raw filesystem errors or other environment details to the model.
158:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
159:           }
160:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
161:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
162:         }
163:         continue;
164:       }
165:       // Keep the answer before anything can reject it. A run that answered without investigating
166:       // at all was rejected here and its answer was lost, which is the failure failed-run.json
167:       // exists to prevent; the preservation path only triggered once this had already been set.
168:       attempt.answer = message.content;
169:       if (!researched()) {
170:         throw new Error('The model proposed a graph without reading repository evidence.');
171:       }
172:       // Seven of ten citations in one run named files the run never opened, one of them a file that
173:       // does not exist. Asking for honest citations has not worked, and repairing them would be
174:       // repair; a citation is checkable against the transcript, so it is checked.
175:       const opened = new Set(investigation
176:         .filter(item => item.tool === 'read_file' && /^\d+: /.test(item.result))
177:         .map(item => item.arguments.path));
178:       // A complete, otherwise valid graph was once discarded because the model wrapped it in a
179:       // markdown fence. Removing that envelope is not JSON repair: malformed JSON inside it,
180:       // a drifted objective or an invalid graph are still rejected exactly as before.
181:       const fenced = message.content.trim().match(/^```[a-z]*\s*\n([\s\S]*?)\n?```$/i);
182:       let graph;
183:       try {
184:         graph = validateGraph(JSON.parse(fenced ? fenced[1] : message.content), objective);
185:       } catch (error) {
