187:       }
188:       const invented = graph.nodes.flatMap(node =>
189:         node.evidence.filter(item => !opened.has(cited(item))).map(item => `${node.id}: ${item}`));
190:       if (invented.length) {
191:         throw new Error(`The graph cites ${invented.length} file(s) this run never read:\n${invented.join('\n')}\nNo repair or retry was made.`);
192:       }
193:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, priorGraph: attempt.priorGraph, investigation };
194:       const html = renderGraph(graph);
195:       keep = true;
196:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
197:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
198:       return join(output, 'graph.html');
199:     }
200:     throw new Error('Investigation limit reached. No graph saved.');
201:   } catch (error) {
202:     if (!attempt.investigation.length && attempt.answer === undefined) throw error;
